INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷111·太祖本纪二·广顺元年三月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/4ae3eabc78dcb3f9ddd203076e0412b51fdf8d20/content/books/zizhi-tongjian/vol-290/year-0951/part-05/sources/library/jiuwudaishi-111-march-policy/source.txt", "note": "《旧五代史》卷111·太祖本纪二·广顺元年三月，段落 jiu-wudaishi-205deb4a7860-p002658；已核上下文及传主，纸本及异文待核。", "id": "9622df11-9945-5d95-a6fb-8f3b86e3dc14"}, {"title": "宋史·卷483·世家六·湖南周氏·周行逢早年", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/4ae3eabc78dcb3f9ddd203076e0412b51fdf8d20/content/books/zizhi-tongjian/vol-290/year-0951/part-05/sources/library/songshi-483-zhou-background/source.txt", "note": "《宋史》卷483·世家六·湖南周氏·周行逢早年，段落 songshi-9c6e46fee832-p075186；已核上下文及传主，纸本及异文待核。", "id": "301503f5-b907-5882-9597-52214e85da36"}, {"title": "资治通鉴·卷290·广顺元年·三月徐州战果与沿淮政策", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/4ae3eabc78dcb3f9ddd203076e0412b51fdf8d20/content/books/zizhi-tongjian/vol-290/year-0951/part-05/sources/library/tongjian-290-951-march-policies/source.txt", "note": "《资治通鉴》卷290·广顺元年·三月徐州战果与沿淮政策，段落 zizhi-tongjian-a63549944a71-p003445；已核上下文及传主，纸本及异文待核。", "id": "5183e5d6-9ce7-5392-aeb1-3712e9138aec"}, {"title": "新五代史·卷66·楚世家·王进逵修府出走", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/4ae3eabc78dcb3f9ddd203076e0412b51fdf8d20/content/books/zizhi-tongjian/vol-290/year-0951/part-05/sources/library/xinwudaishi-066-langzhou-flight/source.txt", "note": "《新五代史》卷66·楚世家·王进逵修府出走，段落 xin-wudaishi-b08f244b9241-p003336；已核上下文及传主，纸本及异文待核。", "id": "f7ff540e-0d30-5629-a06f-b58a414e4c27"}, {"title": "新五代史·卷66·楚世家·刘言与王进逵早年", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/4ae3eabc78dcb3f9ddd203076e0412b51fdf8d20/content/books/zizhi-tongjian/vol-290/year-0951/part-05/sources/library/xinwudaishi-066-wang-background/source.txt", "note": "《新五代史》卷66·楚世家·刘言与王进逵早年，段落 xin-wudaishi-b08f244b9241-p003335；已核上下文及传主，纸本及异文待核。", "id": "3cd4bfb8-a182-5ae8-9530-a6741370cc7a"}, {"title": "资治通鉴·卷290·广顺元年·二三月外交与楚国册封", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/dd3926f483152113be60d810cbf48dffff7b9b14/content/books/zizhi-tongjian/vol-290/year-0951/part-04/sources/library/tongjian-290-951-february-diplomacy/source.txt", "note": "《资治通鉴》卷290·广顺元年·二三月外交与楚国册封，段落 zizhi-tongjian-a63549944a71-p003444；已核上下文及传主，纸本及异文待核。", "id": "4c7666bc-bea9-50da-a518-408a20aabf85"}, {"title": "新五代史·卷11·周本纪·广顺元年", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/7f523fc68334366ce90d3a6e1465b179c9c38000/content/books/zizhi-tongjian/vol-290/year-0951/part-01/sources/library/xinwudaishi-011-first-year-951/source.txt", "note": "《新五代史》卷11·周本纪·广顺元年，段落 xin-wudaishi-b08f244b9241-p000368；已核上下文及传主，纸本及异文待核。", "id": "d3b793df-2c14-5468-91e6-30671d01ef09"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "马希萼", "aliases": ["馬希萼"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "马希范的弟弟、马希广的兄长。947年马希范死时，任武平节度使、知永州事，部分将领主张拥立他，但最终马希广继位。生卒年尚未录入。", "biography": null, "status": "draft", "id": "9d5be246-b5ae-553e-b5c5-a6a875b2c1cd"}, {"name": "马希崇", "aliases": ["馬希崇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "马希广的庶弟、马希萼的弟弟。947年任楚天策左司马，秘密致信马希萼指责继位安排，又向他报告马希广的言行并约为内应。生卒年尚未录入。", "biography": null, "status": "draft", "id": "7c876e99-eb52-5864-9569-0ede35f9ff7b"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "刘光辅", "aliases": ["劉光輔"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "马希萼的掌书记。951年二月奉命向南唐进贡。生卒年未载。", "biography": null, "status": "draft", "id": "f149dc3c-32e5-5f02-bd24-315df551ceee"}, {"name": "边镐", "aliases": ["邊鎬"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "金陵人，南唐通事舍人。943年十月任讨张遇贤军监军，用白昌裕为谋主，接连获胜；白昌裕建议开道绕到营后袭击，张遇贤随后逃走被捕。生卒年尚未核。", "biography": null, "status": "draft", "id": "8bcc0004-3382-5f6c-af6e-73ccf4cdd725"}, {"name": "谢彦颙", "aliases": ["謝彥顒"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "马希萼原来的家奴，担任小门使。《资治通鉴》记他受宠后专横，与马希崇产生嫌隙，并获准参加府宴。生卒年未载。", "biography": null, "status": "draft", "id": "38f0eeff-4fb2-57c8-8650-1fe7b690f7fb"}, {"name": "王逵", "aliases": ["王进逵", "王進逵"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国朗州静江军指挥使。《新五代史》称王进逵，记为武陵人，早年是静江军士卒。951年与周行逢率修府士兵逃回朗州，参与当地军府事务。生卒年尚未录入。", "biography": null, "status": "draft", "id": "48ca3ee4-cced-5056-8a47-4394d3ad6237"}, {"name": "周行逢", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国朗州静江军副使。951年与王逵率修府士兵逃回朗州。《宋史》记为朗州武陵人，早年因犯法被编入军队，凭骁勇升任军官。生卒年尚未录入。", "biography": null, "status": "draft", "id": "1bc0f62b-e1c1-5468-a9db-2d2d5444ab22"}, {"name": "唐师翥", "aliases": ["唐師翥", "唐翥"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国湖南指挥使。951年奉马希萼命令追赶王逵等，在朗州遭伏击，败后逃回。《新五代史》同一追击记载称唐翥。生卒年未载。", "biography": null, "status": "draft", "id": "74115e35-b7c4-5bb9-bfc7-4feed4a02c3d"}, {"name": "马光赞", "aliases": ["馬光贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "马希萼的儿子。950年十一月，马希萼率军向长沙进发，留下他守朗州。生卒年和母亲身份未载。", "biography": null, "status": "draft", "id": "3fbbf096-7e41-591f-8fb9-2c5b3cb24eb3"}, {"name": "马光惠", "aliases": ["馬光惠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "马希振之子、马希萼的侄子。951年王逵等罢免马光赞后，让他主持朗州事务，随后拥立他为节度使。生卒年未载。", "biography": null, "status": "draft", "id": "59cfaa85-b7b4-5c24-a5e5-f54754f04076"}, {"name": "马希振", "aliases": ["馬希振"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "马光惠的父亲。《资治通鉴》在951年朗州政局记载中明确说明这项亲属关系，未提供其生卒年。", "biography": null, "status": "draft", "id": "8405bc11-e2ed-5a84-a630-61aa2f281fc3"}, {"name": "何敬真", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "武陵人，朗州步军指挥使。950年率部族兵攻破韩礼在杨柳桥的防线；马希萼入长沙后任他为朗州牙内都指挥使，率兵戍守。生卒年未载。", "biography": null, "status": "draft", "id": "0ce9ccfa-b68b-575c-96b0-8022528be7ad"}, {"name": "张亻放（楚军指挥使）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国诸军指挥使。951年与王逵、周行逢、何敬真共同处理朗州军府事务。电子底本姓名末字写作“亻放”，字形待核，暂不与其他记载中的张仿合并。生卒年未载。", "biography": null, "status": "draft", "id": "b66c1113-4e1b-5c98-9a58-2258c1bad288"}, {"name": "王彦超", "aliases": ["王彥超"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "临清人，后晋护圣指挥使。946年六月受命与白延遇带所属十营兵赴邢州。生卒年未载。", "biography": null, "status": "draft", "id": "c981d4c7-7693-5ee8-a667-6ab1fccba981"}, {"name": "巩延美", "aliases": ["鞏延美", "巩庭美", "鞏庭美", "巩廷美", "鞏廷美"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘赟的右都押牙。950年刘赟离开徐州西行迎立时，与杨温留守徐州。《新五代史》刘赟传写作巩庭美，同职同伴及同一留守场景对应；生卒年本批未录。", "biography": null, "status": "draft", "id": "4df9296b-060c-55ce-9ca5-a4523a55428f"}, {"name": "杨温", "aliases": ["楊溫"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘赟的元从都教练使。950年刘赟离开徐州西行迎立时，与巩延美留守徐州。生卒年本批未录。", "biography": null, "status": "draft", "id": "899b9466-92c5-5e46-b835-0d2e7cfdbf64"}, {"name": "李巩言", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "北汉通事舍人。951年奉刘崇派遣出使契丹，请求援兵。生卒年未载。", "biography": null, "status": "draft", "id": "f2ad0b09-607f-5d5a-9e94-6773cfb0518b"}, {"name": "耶律阮", "aliases": ["耶律兀欲", "兀欲", "永康王"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "小字兀欲，东丹王耶律倍之子。《资治通鉴》947年条下称永康王，记耶律德光将李彦绅、秦继旻的家属和财产交给他。《辽史》卷五明确名阮、小字兀欲，按同一主体建档；王号具体授封时间仍须另据后文校核，生卒年暂未录。", "biography": null, "status": "draft", "id": "42a17de5-aa28-50e6-bab8-b134f0113f3f"}, {"name": "拽剌梅里（951年契丹使者）", "aliases": ["拽剌梅里"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "951年耶律阮派遣的使者，负责答复北汉来使李巩言。姓名及梅里称谓仍待校核，暂不与其他年代的同称使臣合并。生卒年未载。", "biography": null, "status": "draft", "id": "fe925244-c505-5ac3-b076-e0993cf90435"}, {"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

